58	interface VinylPlayerProps {
59	  projectId: string;
60	  onNavigateToIngestion?: () => void;
61	  navigateTo?: (tab: string) => void;
62	}
63	
64	declare global {
65	  interface Window {
66	    YT: any;
67	    onYouTubeIframeAPIReady: (() => void) | undefined;
68	  }
69	}
70	
71	const TIMEBLOCK_ARCS = [
72	  { id: 'Arc Zero ~ Kick Starter', label: 'Arc Zero ~ Kick Starter', emoji: '🌊', fullRow: true },
73	  { id: 'Arc 01 ~ Morning Star - Raye', label: 'Arc 01 ~ Morning Star - Raye', emoji: '🚀', fullRow: false },
74	  { id: 'Arc 02 ~ Battle Phase - Racheal', label: 'Arc 02 ~ Battle Phase - Racheal', emoji: '⚔️', fullRow: false },
75	  { id: 'Arc 03 ~ Night Hours Melody', label: 'Arc 03 ~ Night Hours Melody', emoji: '🌙', fullRow: false },
76	  { id: 'Arc 04 ~ Sacred Pragma', label: 'Arc 04 ~ Sacred Pragma', emoji: '🪶', fullRow: false },
77	];
78	
79	export const VinylPlayer: React.FC<VinylPlayerProps> = ({
80	  projectId,
81	  onNavigateToIngestion,
82	  navigateTo,
83	}) => {
84	  const targetProjectId = !projectId || projectId === 'vinyl_angel' ? 'music_app' : projectId;
85	
86	  const {
87	    settings,
88	    discs,
89	    earnDiscs,
90	    incrementRatingStats,
91	    equippedStylus,
92	    stats,
93	    queuedTrackForGameplay,
94	    setQueuedTrackForGameplay,
95	    queuedPlaylistForGameplay,
96	    setQueuedPlaylistForGameplay,
97	    offlineOutbox = [],
98	    enqueueOfflineEvent,
99	    clearOfflineOutbox,
100	    customPlaylists,
101	    setCustomPlaylists,
102	    channelList,
103	    setChannelList,
104	    channelMetaMap,
105	    setChannelMetaMap,
106	    addBlockedSong,
107	  } = useVinylStore();
108	
109	  // Sorting & Filtering parameters: channel_name, excluded_channels, and hazard_cap (from File 1 & File 4)
110	  const [selectedChannel, setSelectedChannel] = useState<string>('ALL');
111	  const [excludedChannels, setExcludedChannels] = useState<string[]>([]);
112	  const [hazardCap, setHazardCap] = useState<string>('3.2');
113	  const [isExcludeDropdownOpen, setIsExcludeDropdownOpen] = useState<boolean>(false);
114	  const [excludeSearchQuery, setExcludeSearchQuery] = useState<string>('');
115	  const [isPlaylistModalOpen, setIsPlaylistModalOpen] = useState<boolean>(false);
116	  const [excludeTab, setExcludeTab] = useState<'playlists' | 'channels'>('playlists');
117	
118	  const excludeDropdownRef = useRef<HTMLDivElement>(null);
119	
120	  // Categorize channels by their curation status (Approved, Cleaning, Raw)
121	  const { approvedChannels, cleaningChannels, rawChannels } = useMemo(() => {
122	    const app: ChannelOriginItem[] = [];
123	    const cln: ChannelOriginItem[] = [];
124	    const raw: ChannelOriginItem[] = [];
125	
126	    channelList.forEach((ch) => {
127	      const st =
128	        channelMetaMap[ch.channel_id || '']?.status ||
129	        channelMetaMap[ch.name]?.status ||
130	        'raw';
131	      if (st === 'approved') app.push(ch);
132	      else if (st === 'cleaning') cln.push(ch);
133	      else raw.push(ch);
134	    });
135	
136	    return { approvedChannels: app, cleaningChannels: cln, rawChannels: raw };
137	  }, [channelList, channelMetaMap]);
138	
139	  // Track pool & Catalog state
140	  const [playlist, setPlaylist] = useState<PlaylistItem[]>([]);
141	  const [totalCatalogCount, setTotalCatalogCount] = useState<number>(0);
142	  const [sessionRatedCount, setSessionRatedCount] = useState<number>(0);
143	  const [currentIndex, setCurrentIndex] = useState<number>(-1);
144	  const [displayStats, setDisplayStats] = useState<Record<string, TrackDisplayMeta>>({});
145	  const [currentProbability, setCurrentProbability] = useState<number | null>(null);
146	
147	  // Connection, Watchdog & Outbox Lifecycle state
148	  const [isLoading, setIsLoading] = useState<boolean>(true);
149	  const [isOffline, setIsOffline] = useState<boolean>(false);
150	  const [isLoudFailure, setIsLoudFailure] = useState<boolean>(false);
151	  const [isRetrying, setIsRetrying] = useState<boolean>(false);
152	  const [isFlushingOutbox, setIsFlushingOutbox] = useState<boolean>(false);
153	  const [errorMessage, setErrorMessage] = useState<string | null>(null);
154	  const [isExhausted, setIsExhausted] = useState<boolean>(false);
155	
156	  const consecutiveFailuresRef = useRef<number>(0);
157	
158	  // Rating controls state
159	  const [ratingTarget, setRatingTarget] = useState<'track' | 'channel'>('track');
160	  const [selectedScore, setSelectedScore] = useState<ScoreTier | ''>('');
161	  const [selectedArcs, setSelectedArcs] = useState<string[]>([]);
162	  const [isLogging, setIsLogging] = useState<boolean>(false);
163	  const [stagedHazardRank, setStagedHazardRank] = useState<number | null>(5);
164	  const [isRatingPinned, setIsRatingPinned] = useState<boolean>(false);
165	  const [pendingLogsCount, setPendingLogsCount] = useState<number>(0);
166	  const [toast, setToast] = useState<{ message: string; type?: 'info' | 'success' | 'warn' | 'error' } | null>(null);
167	
168	  // References to eliminate circular effects, stale closures, and player race conditions
169	  const playerRef = useRef<any>(null);
170	  const isPlayerReadyRef = useRef<boolean>(false);
171	  const isAutoSyncingRef = useRef<boolean>(false);
172	  const isRatingPinnedRef = useRef<boolean>(false);
173	  const currentlyLoadedVideoIdRef = useRef<string | null>(null);
174	  const pendingVideoIdRef = useRef<string | null>(null);
175	  const lastLoggedTrackIdRef = useRef<string | null>(null);
176	  const playlistRef = useRef<PlaylistItem[]>([]);
177	  const displayStatsRef = useRef<Record<string, TrackDisplayMeta>>({});
178	  const currentIndexRef = useRef<number>(-1);
179	  const currentTrackRef = useRef<PlaylistItem | null>(null);
180	  const selectedArcsRef = useRef<string[]>([]);
181	  const selectedScoreRef = useRef<ScoreTier | ''>('');
182	  const stagedHazardRankRef = useRef<number | null>(5);
183	  const selectedChannelRef = useRef<string>('ALL');
184	  const excludedChannelsRef = useRef<string[]>([]);
185	  const hazardCapRef = useRef<string>('3.2');
186	  const settingsRef = useRef(settings);
187	  const consecutiveErrorsRef = useRef<number>(0);
188	  const isMountedRef = useRef<boolean>(true);
189	  const isFetchingMoreRef = useRef<boolean>(false);
190	  const seenIdsRef = useRef<Set<string>>(new Set());
191	
192	  // Derived current active track
193	  const currentTrack =
194	    currentIndex >= 0 && currentIndex < playlist.length ? playlist[currentIndex] : null;
195	
196	  // Synchronize ref mirrors
197	  playlistRef.current = playlist;
198	  displayStatsRef.current = displayStats;
199	  currentIndexRef.current = currentIndex;
200	  currentTrackRef.current = currentTrack;
201	  selectedArcsRef.current = selectedArcs;
202	  selectedScoreRef.current = selectedScore;
203	  stagedHazardRankRef.current = stagedHazardRank;
204	  isRatingPinnedRef.current = isRatingPinned;
205	  selectedChannelRef.current = selectedChannel;
206	  excludedChannelsRef.current = excludedChannels;
207	  hazardCapRef.current = hazardCap;
208	  settingsRef.current = settings;
209	
210	  // Close exclude popover on outside click
211	  useEffect(() => {
212	    const handleClickOutside = (event: MouseEvent) => {
213	      if (
214	        excludeDropdownRef.current &&
215	        !excludeDropdownRef.current.contains(event.target as Node)
216	      ) {
217	        setIsExcludeDropdownOpen(false);
218	      }
219	    };
220	    if (isExcludeDropdownOpen) {
221	      document.addEventListener('mousedown', handleClickOutside);
222	    }
223	    return () => {
224	      document.removeEventListener('mousedown', handleClickOutside);
225	    };
226	  }, [isExcludeDropdownOpen]);
227	
228	  // Filter channels inside dropdown search
229	  const filteredExcludeChannels = useMemo(() => {
230	    if (!excludeSearchQuery.trim()) return channelList;
231	    const q = excludeSearchQuery.toLowerCase().trim();
232	    return channelList.filter((ch) => ch.name.toLowerCase().includes(q));
233	  }, [channelList, excludeSearchQuery]);
234	
235	  const showToast = useCallback((message: string, type: 'info' | 'success' | 'warn' | 'error' = 'info') => {
236	    setToast({ message, type });
237	    setTimeout(() => {
238	      if (isMountedRef.current) setToast(null);
239	    }, 3000);
240	  }, []);
241	
242	  const getPlayedCount = useCallback((trackId: string): number => {
243	    const val = displayStatsRef.current[String(trackId)];
244	    return val && Number.isInteger(val.played) && val.played >= 0 ? val.played : 0;
245	  }, []);
246	
247	  const getHazardLevel = useCallback((trackId: string): number => {
248	    const val = displayStatsRef.current[String(trackId)];
249	    return val && !isNaN(val.hazard_level) ? val.hazard_level : 3.0;
250	  }, []);
251	
252	  // Authoritative YouTube video synchronization function
253	  const syncVideoToPlayer = useCallback((targetVideoId: string | null) => {
254	    if (!targetVideoId) return;
255	
256	    if (!isPlayerReadyRef.current || !playerRef.current) {
257	      pendingVideoIdRef.current = targetVideoId;
258	      return;
259	    }
260	
261	    if (currentlyLoadedVideoIdRef.current === targetVideoId) {
262	      return;
263	    }
264	
265	    try {
266	      currentlyLoadedVideoIdRef.current = targetVideoId;
267	      pendingVideoIdRef.current = null;
268	      playerRef.current.loadVideoById({
269	        videoId: String(targetVideoId).trim(),
270	        startSeconds: 0,
271	      });
272	      playerRef.current.playVideo();
273	    } catch (err) {
274	      console.warn('[YouTube Player] loadVideoById error:', err);
275	    }
276	  }, []);
277	
278	  // Synchronize YouTube player whenever currentTrack changes
279	  useEffect(() => {
280	    if (currentTrack && currentTrack.id) {
281	      syncVideoToPlayer(currentTrack.id);
282	    }
283	  }, [currentTrack?.id, syncVideoToPlayer]);
284	
285	  // Zero-allocation O(N) roulette selection
286	  const selectWeightedTrack = useCallback((list: PlaylistItem[], excludeIdx: number = -1) => {
287	    if (!list || list.length === 0) {
288	      return { index: -1, probability: 0 };
289	    }
290	
291	    const n = list.length;
292	    if (n === 1) {
293	      return { index: 0, probability: 100 };
294	    }
295	
296	    let totalWeight = 0;
297	    for (let i = 0; i < n; i++) {
298	      if (i === excludeIdx) continue;
299	      const count = displayStatsRef.current[list[i].id]?.played ?? 0;
300	      totalWeight += 1 / (count + 1);
301	    }
302	
303	    if (totalWeight <= 0) return { index: 0, probability: 100 };
304	
305	    let randomVal = Math.random() * totalWeight;
306	    let selectedIndex = 0;
307	    let selectedWeight = 1;
308	
309	    for (let i = 0; i < n; i++) {
310	      if (i === excludeIdx) continue;
311	      const count = displayStatsRef.current[list[i].id]?.played ?? 0;
312	      const w = 1 / (count + 1);
313	      randomVal -= w;
314	      if (randomVal <= 0) {
315	        selectedIndex = i;
316	        selectedWeight = w;
317	        break;
318	      }
319	    }
320	
321	    const probability = (selectedWeight / totalWeight) * 100;
322	    return { index: selectedIndex, probability };
323	  }, []);
324	
325	  // Play track by index and trigger state synchronization
326	  const playTrackByIndex = useCallback((idx: number, currentList: PlaylistItem[], prob: number | null = null) => {
327	    if (idx < 0 || idx >= currentList.length) return;
328	
329	    setCurrentIndex(idx);
330	    currentIndexRef.current = idx;
331	    setCurrentProbability(prob);
332	    setSelectedArcs([]);
333	    if (!isRatingPinnedRef.current) {
334	      setSelectedScore('');
335	      selectedScoreRef.current = '';
336	    }
337	  }, []);
338	
339	  // Replenish playlist buffer from backend in background respecting channel_name, excluded_channels, and hazard_cap
340	  const replenishBufferIfNeeded = useCallback(async () => {
341	    if (isFetchingMoreRef.current || playlistRef.current.length >= 15) return;
342	
343	    isFetchingMoreRef.current = true;
344	    try {
345	      let customChannels: string[] | undefined = undefined;
346	      let singleChannel: string | undefined = selectedChannelRef.current;
347	
348	      if (singleChannel && singleChannel.startsWith('CUSTOM:')) {
349	        const plId = singleChannel.replace('CUSTOM:', '');
350	        const pl = useVinylStore.getState().customPlaylists.find((p) => p.id === plId);
351	        if (pl && pl.channels.length > 0) {
352	          customChannels = pl.channels;
353	          singleChannel = undefined;
354	        }
355	      } else if (singleChannel === 'STATUS:approved') {
356	        customChannels = approvedChannels.map((c) => c.name);
357	        singleChannel = undefined;
358	      } else if (singleChannel === 'STATUS:cleaning') {
359	        customChannels = cleaningChannels.map((c) => c.name);
360	        singleChannel = undefined;
361	      } else if (singleChannel === 'STATUS:raw') {
362	        customChannels = rawChannels.map((c) => c.name);
363	        singleChannel = undefined;
364	      }
365	
366	      const blockedRaw = useVinylStore.getState().blockedSongIds;
367	      const blocked = Array.isArray(blockedRaw) ? blockedRaw : [];
368	      const moreTracks = await fetchMoreSampledTracks(
369	        targetProjectId,
370	        50,
371	        singleChannel,
372	        hazardCapRef.current,
373	        excludedChannelsRef.current,
374	        customChannels,
375	        blocked.length > 0 ? blocked : undefined
376	      );
